<!--
 * 死信队列列表页组件
 *
 * @path apps/message-web/src/views/dead-letter/index.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为消费契约 API（页面询 + 重发），删除无创建语义的表单。
-->
<script lang="ts" setup>
/**
 * 死信队列（列表页）
 * <p>消费后端契约 DeadLetterController（src/api/dead-letter.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询死信消息，行操作「重发」调 resend({logId})。死信无创建语义，故不提供表单。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElTag } from 'element-plus';
import { h } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { page, resend } from '#/api/deadLetter';
import type { MsgLogVO } from '#/api/models';

defineOptions({ name: 'DeadLetterManagement' });

/** 状态列 Tag 类型映射（死信多为失败态，未知值按 info 展示） */
function getStatusType(status?: string): 'success' | 'danger' | 'warning' | 'info' {
  const upper = (status ?? '').toUpperCase();
  if (['SUCCESS', 'RESENT', 'RECOVERED'].includes(upper)) return 'success';
  if (['DEAD', 'FAILED', 'ERROR'].includes(upper)) return 'danger';
  if (['RETRY', 'PENDING', 'PROCESSING'].includes(upper)) return 'warning';
  return 'info';
}

const gridOptions: VxeTableGridOptions<MsgLogVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'msgId', title: '消息ID', width: 180 },
    { field: 'channel', title: '通道', width: 100 },
    { field: 'bizType', title: '业务类型', width: 110 },
    { field: 'receiver', title: '接收者', width: 140 },
    { field: 'errorMessage', title: '错误信息', width: 220 },
    { field: 'retryCount', title: '重试次数', width: 90 },
    {
      field: 'status',
      title: '状态',
      width: 100,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: getStatusType(row.status) }, () => row.status ?? '-'),
      },
    },
    { field: 'createdAt', title: '创建时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 90,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h(
            ElButton,
            { size: 'small', link: true, type: 'primary', onClick: () => handleResend(row) },
            () => '重发',
          ),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({ query: { ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'channel',
        title: '通道',
        itemRender: { name: 'Input', props: { placeholder: '通道' } },
      },
      {
        field: 'bizType',
        title: '业务类型',
        itemRender: { name: 'Input', props: { placeholder: '业务类型' } },
      },
      {
        field: 'keyword',
        title: '关键词',
        itemRender: { name: 'Input', props: { placeholder: '消息ID/接收者' } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

async function handleResend(row: MsgLogVO) {
  if (!row.id) return;
  try {
    await resend({ logId: row.id });
    ElMessage.success('重发成功');
    gridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="死信队列" />
  </Page>
</template>
